windowclass.script:
function isTag()
				return self.is_tag_chk and self.is_tag_chk.getValue() == 1;
			end

			function setReadOnlyIfSupported(c, bReadOnly)
				if c and c.setReadOnly then
					c.setReadOnly(bReadOnly);
				end
			end

			function setStatPowerControlsReadOnly(bReadOnly)
				for i = 1, 6 do
					self.setReadOnlyIfSupported(self["statlvl" .. i], bReadOnly);
				end

				self.setReadOnlyIfSupported(self.stpower_dd, bReadOnly);
			end

			function forceTagPower()
				for i = 1, 6 do
					local cStatLevel = self["statlvl" .. i];
					if cStatLevel then
						local nValue = 0;
						if i == 1 then
							nValue = 1;
						end

						if cStatLevel.getValue() ~= nValue then
							cStatLevel.setValue(nValue);
						end
					end
				end

				if self.stpower_dd and self.stpower_dd.getValue() ~= "1" then
					self.stpower_dd.setValue("1");
				end
			end

			function updateTagLockState()
				local bTag = self.isTag();
				if bTag then
					self.forceTagPower();
				end

				self.setStatPowerControlsReadOnly(bTag);
			end

			function clampStatPowerDropdown()
				if self.isTag() then
					self.forceTagPower();
				end
			end

			function onInit()
				self.updateTagLockState();
			end

			function updateStatPowerDropdown()
				if self.isTag() then
					self.forceTagPower();
					return;
				end

				local nHighest = 0;

				for i = 1, 6 do
					local sControlName = "statlvl" .. i;

					if self[sControlName] and self[sControlName].getValue() == 1 then
						nHighest = i;
					end
				end

				if self.stpower_dd then
					if nHighest > 0 then
						self.stpower_dd.setValue(tostring(nHighest));
					else
						self.stpower_dd.setValue("");
					end
				end

				self.updateTagLockState();
			end

