					function getActorNode()
						local node = window.getDatabaseNode();

						-- If this is inside a list row, climb upward until we find the actor node.
						while node do
							if DB.getValue(node, "name", "") ~= "" then
								return node;
							end

							node = node.getParent();
						end

						return nil;
					end

					function getActorNameFromNode(nodeActor)
						if not nodeActor then
							return "Unknown Actor";
						end

						local rActor = ActorManager.resolveActor(nodeActor);
						if rActor then
							return ActorManager.getDisplayName(rActor);
						end

						return DB.getValue(nodeActor, "name", "Unknown Actor");
					end

					function getStatusTagName()
						local sStatusTag = "Status Tag";

						if window.statustag_string then
							sStatusTag = window.statustag_string.getValue();
						end

						if not sStatusTag or sStatusTag == "" then
							sStatusTag = "Status Tag";
						end

						return sStatusTag;
					end

					function getModifierText(nMod)
						if nMod >= 0 then
							return "+" .. nMod;
						end

						return tostring(nMod);
					end

					function sendModMessageToAll(sText)
						local msg = {};
						msg.font = "msgfont";
						msg.text = sText;

						Comm.deliverChatMessage(msg);
					end

					function onClickDown(button, x, y)
						-- onClickDown fires before the checkbox changes.
						-- getValue() == 0 means this click is checking the box.
						-- getValue() == 1 means this click is unchecking the box.
						if getValue() ~= 0 then
							return true;
						end

						local nPower = 0;

						if window.stpower_dd then
							nPower = tonumber(window.stpower_dd.getValue()) or 0;
						end

						if nPower ~= 0 then
							local sStatusTag = getStatusTagName();

							ModifierStack.addSlot(sStatusTag, nPower);

							local nodeActor = getActorNode();
							local sActorName = getActorNameFromNode(nodeActor);

							sendModMessageToAll(sActorName .. " added " .. getModifierText(nPower) .. " from " .. sStatusTag);
						end

						return true;
					end

					function onValueChanged()
						-- Leave empty.
						-- Do not add ModifierStack or chat message code here.
					end

